#[cfg(test)]
mod tests {
    use super::*;

    /// Octets written as two hex digits each, separated by spaces.
    fn octets(hex: &str) -> Vec<u8> {
        hex.split_whitespace()
            .map(|pair| u8::from_str_radix(pair, 16).unwrap())
            .collect()
    }

    #[test]
    fn no_octets_are_incomplete() {
        assert_eq!(parse(&[]), Err(Error::Incomplete));
    }

    #[test]
    fn vector_z_0_accepted() {
        let bytes = octets("00 00 00 00 00 00 00 00 00 00 00 00");
        let (header, used) = parse(&bytes).unwrap();
        assert_eq!(header.z, 0);
        assert_eq!(used, bytes.len());
        assert_eq!(print(&header), bytes);
    }

    #[test]
    fn vector_z_1_refused() {
        let bytes = octets("00 00 00 10 00 00 00 00 00 00 00 00");
        assert_eq!(
            parse(&bytes),
            Err(Error::Constraint {
                field: "z",
                value: 1
            })
        );
    }
}
